#!/usr/bin/env python

import numpy as np
import math
import matplotlib.pyplot as plt
from   pylab import *

## Create three plots: average density, concentration, and diameter
fig1 = plt.figure()
denPlot = plt.subplot(311)
concPlot = plt.subplot(312)
diamPlot = plt.subplot(313)

## Open the data file generated by Xolotl (default is Alloy.dat)
if len(sys.argv) > 1:
    filename = sys.argv[1]
else:
    filename = 'monitor.dat'

t = loadtxt(filename, unpack=True)
nspec = int((len(t) - 1) / 6)

## Get species names
with open(filename, 'r') as file:
    header = file.readline()
specLabels = ['species_' + str(i) for i in range(nspec)]
if header.startswith("#"):
    varLabels = header.split()
    for i in range(nspec):
        varid = i * 6 + 1
        specLabels[i] = varLabels[varid].split('_')[0]

time = t[0]
dose = time * 4.0e-7

for i in range(nspec):
    varid = i * 6 + 1
    den = t[varid] * 1.0e27
    denPlot.plot(dose, den, lw=4, alpha=0.7, label=specLabels[i])
    conc = t[varid + 1] * 1.0e27
    concPlot.plot(dose, conc, lw=4, alpha=0.7, label=specLabels[i])
    diam = t[varid + 2]
    diamPlot.plot(dose, diam, lw=4, alpha=0.7, label=specLabels[i])

## Plot the legend
l = denPlot.legend(loc='best')
setp(l.get_texts(), fontsize=20)

## Some shaping
denPlot.set_xlabel("Dose (dpa)",fontsize=14)
denPlot.set_ylabel("Density (m-3)",fontsize=14)
denPlot.set_xlim([1.0e-6, 1.0e-2])
# denPlot.set_ylim([1.0e23, 8.0e23])
denPlot.set_xscale('log')
denPlot.set_yscale('log')
denPlot.grid()
denPlot.tick_params(axis='both', which='major', labelsize=14)
denPlot.tick_params(axis='both', which='minor', labelsize=14)

concPlot.set_xlabel("Dose (dpa)",fontsize=14)
concPlot.set_ylabel("Concentration (m-3)",fontsize=14)
concPlot.set_xlim([1.0e-6, 1.0e-2])
# concPlot.set_ylim([1.0e23, 8.0e23])
concPlot.set_xscale('log')
concPlot.set_yscale('log')
concPlot.grid()
concPlot.tick_params(axis='both', which='major', labelsize=14)
concPlot.tick_params(axis='both', which='minor', labelsize=14)

diamPlot.set_xlabel("Dose (dpa)",fontsize=14)
diamPlot.set_ylabel("Diameter (nm)",fontsize=14)
diamPlot.set_xlim([1.0e-6, 1.0e-2])
#diamPlot.set_ylim([0.0, 4.0])
diamPlot.set_xscale('log')
diamPlot.set_yscale('log')
diamPlot.grid()
diamPlot.tick_params(axis='both', which='major', labelsize=14)
diamPlot.tick_params(axis='both', which='minor', labelsize=14)

## Show the plots
plt.show()
